  document.querySelectorAll('.flow-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      document.querySelectorAll('.flow-tab').forEach(t => {
        t.classList.remove('bg-surface-container-high', 'text-primary', 'font-semibold');
        t.classList.add('text-on-surface-variant');
      });
      tab.classList.add('bg-surface-container-high', 'text-primary', 'font-semibold');
      tab.classList.remove('text-on-surface-variant');

      const key = tab.getAttribute('data-flow');
      const data = flowTemplates[key];
      if (data) {
        document.getElementById('flowContent').innerHTML = `
          <div class="flex items-center justify-between text-on-surface font-label-mono text-label-mono">
            <span class="text-primary font-semibold">${data.title}</span>
            <span class="text-on-surface-variant">${data.runtime}</span>
          </div>
          <div class="grid grid-cols-1 md:grid-cols-3 gap-space-sm pt-space-xs">
            <div class="p-space-sm rounded bg-surface-container-low flex flex-col gap-1">
              <span class="font-label-mono text-label-mono text-primary font-semibold">STAGE 01</span>
              <p class="font-body-sm text-body-sm text-on-surface-variant">${data.step1}</p>
            </div>
            <div class="p-space-sm rounded bg-surface-container-low flex flex-col gap-1">
              <span class="font-label-mono text-label-mono text-primary-container font-semibold">STAGE 02</span>
              <p class="font-body-sm text-body-sm text-on-surface-variant">${data.step2}</p>
            </div>
            <div class="p-space-sm rounded bg-surface-container-low flex flex-col gap-1">
              <span class="font-label-mono text-label-mono text-tertiary-fixed-dim font-semibold">STAGE 03</span>
              <p class="font-body-sm text-body-sm text-on-surface-variant">${data.step3}</p>
            </div>
          </div>
        `;
      }
    });
  });

  document.querySelectorAll('.quick-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      const textarea = document.querySelector('textarea');
      if (textarea) {
        textarea.value = chip.textContent.trim();
        textarea.focus();
      }
    });
  });

// Simple micro-interaction for simulation toggle button
  document.getElementById('simToggle')?.addEventListener('click', function() {
    const icon = this.querySelector('span');
    if (icon.innerText === 'pause_circle') {
      icon.innerText = 'play_circle';
      this.classList.add('text-primary');
    } else {
      icon.innerText = 'pause_circle';
      this.classList.remove('text-primary');
    }
  });

// Micro-interaction for air-gap visual toggle
  document.getElementById('toggleAirgap')?.addEventListener('click', function(e) {
    const knob = this.querySelector('span');
    if (this.classList.contains('bg-primary-container')) {
      this.classList.remove('bg-primary-container');
      this.classList.add('bg-surface-container-highest');
      knob.classList.remove('translate-x-4');
      knob.classList.add('translate-x-0');
    } else {
      this.classList.add('bg-primary-container');
      this.classList.remove('bg-surface-container-highest');
      knob.classList.add('translate-x-4');
      knob.classList.remove('translate-x-0');
    }
  });

(function initPluginCentre() {
      // Tab switching
      const tabs = document.querySelectorAll('.tab-btn');
      tabs.forEach(tab => {
        tab.addEventListener('click', () => {
          tabs.forEach(t => {
            t.classList.remove('bg-secondary-container', 'text-on-secondary-container', 'font-semibold');
            t.classList.add('text-on-surface-variant', 'font-medium');
          });
          tab.classList.add('bg-secondary-container', 'text-on-secondary-container', 'font-semibold');
          tab.classList.remove('text-on-surface-variant', 'font-medium');
        });
      });

      // Filter pills
      const filterPills = document.querySelectorAll('.filter-pill');
      filterPills.forEach(pill => {
        pill.addEventListener('click', () => {
          filterPills.forEach(p => {
            p.classList.remove('bg-surface-container-high', 'text-primary', 'font-semibold');
            p.classList.add('bg-surface-container-low', 'text-on-surface-variant');
          });
          pill.classList.add('bg-surface-container-high', 'text-primary', 'font-semibold');
          pill.classList.remove('bg-surface-container-low', 'text-on-surface-variant');
        });
      });

      // Plugin card click selection
      const cards = document.querySelectorAll('.plugin-card');
      cards.forEach(card => {
        card.addEventListener('click', () => {
          cards.forEach(c => {
            c.classList.remove('bg-surface-container-high');
            c.classList.add('bg-surface-container');
          });
          card.classList.remove('bg-surface-container');
          card.classList.add('bg-surface-container-high');
        });
      });

      // Quick key listener for search input
      window.addEventListener('keydown', (e) => {
        if (e.key === '/' && document.activeElement.tagName !== 'INPUT') {
          e.preventDefault();
          const search = document.getElementById('plugin-search');
          if (search) search.focus();
        }
      });
    })();

// Simple client-side micro-interactions for agent search and selection
  document.addEventListener('DOMContentLoaded', () => {
    const searchInput = document.getElementById('agent-search');
    const cards = document.querySelectorAll('.agent-card');
    const filterButtons = document.querySelectorAll('.filter-btn');

    if (searchInput) {
      searchInput.addEventListener('input', (e) => {
        const query = e.target.value.toLowerCase();
        cards.forEach(card => {
          const text = card.innerText.toLowerCase();
          card.style.display = text.includes(query) ? 'block' : 'none';
        });
      });
    }

    filterButtons.forEach(btn => {
      btn.addEventListener('click', () => {
        filterButtons.forEach(b => {
          b.classList.remove('bg-secondary-container', 'text-on-secondary-container', 'font-semibold');
          b.classList.add('text-on-surface-variant');
        });
        btn.classList.add('bg-secondary-container', 'text-on-secondary-container', 'font-semibold');
        btn.classList.remove('text-on-surface-variant');
      });
    });

    cards.forEach(card => {
      card.addEventListener('click', () => {
        cards.forEach(c => c.classList.remove('ring-1', 'ring-secondary-container/40'));
        card.classList.add('ring-1', 'ring-secondary-container/40');
      });
    });
  });

// Emergency stop interaction & Escape x2 key handler
  let lastEscTime = 0;
  window.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      const now = Date.now();
      if (now - lastEscTime < 400) {
        triggerEmergencyHalt();
      }
      lastEscTime = now;
    }
  });

  const haltBtn = document.getElementById('emergency-halt-btn');
  if (haltBtn) {
    haltBtn.addEventListener('click', triggerEmergencyHalt);
  }

  function triggerEmergencyHalt() {
    alert('EMERGENCY STOP EXECUTED: All peripheral input simulation hooks instantly unhooked. Active subroutines frozen.');
  }

// Hotkey listener for '/' search trigger
    document.addEventListener('keydown', function(e) {
      if (e.key === '/' && document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA') {
        e.preventDefault();
        const searchInput = document.getElementById('vector-search-input');
        if (searchInput) {
          searchInput.focus();
          searchInput.select();
        }
      }
    });

    // Forget Modal Logic
    function openForgetModal(targetTitle) {
      const modal = document.getElementById('forget-modal');
      const targetText = document.getElementById('forget-target-title');
      if (modal && targetText) {
        targetText.textContent = targetTitle;
        modal.classList.remove('hidden');
        modal.classList.add('flex');
      }
    }

    function closeForgetModal() {
      const modal = document.getElementById('forget-modal');
      if (modal) {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
      }
    }

    function confirmForget() {
      closeForgetModal();
    }

    // Manual Memory Modal Logic
    const btnManual = document.getElementById('btn-manual-mem');
    const manualModal = document.getElementById('manual-mem-modal');

    if (btnManual && manualModal) {
      btnManual.addEventListener('click', () => {
        manualModal.classList.remove('hidden');
        manualModal.classList.add('flex');
      });
    }

    function closeManualMemModal() {
      if (manualModal) {
        manualModal.classList.add('hidden');
        manualModal.classList.remove('flex');
      }
    }

    // Purge Store Button Shortcut Trigger
    const btnPurge = document.getElementById('btn-purge-open');
    if (btnPurge) {
      btnPurge.addEventListener('click', () => {
        openForgetModal('ENTIRE LOCAL STORE (54,120 Embeddings)');
      });
    }

(function () {
    const playBtn = document.getElementById('playSampleBtn');
    if (playBtn) {
      playBtn.addEventListener('click', function () {
        const icon = playBtn.querySelector('.material-symbols-outlined');
        if (icon) {
          icon.textContent = icon.textContent === 'play_arrow' ? 'pause' : 'play_arrow';
          setTimeout(() => {
            icon.textContent = 'play_arrow';
