      calibrateBtn.addEventListener('click', function () {
        vuVal.textContent = 'CALIBRATING...';
        vuVal.classList.add('text-secondary');
        setTimeout(() => {
          vuVal.textContent = '-14 dBFS (Calibrated)';
          vuVal.classList.remove('text-secondary');
