(function highlightNav() {
      const targetPath = 'tasks-activity';
      const navLinks = document.querySelectorAll('aside nav a');
      navLinks.forEach(link => {
        if (link.getAttribute('data-path') === targetPath) {
          link.className = 'flex items-center gap-space-md px-space-sm py-space-xs rounded bg-secondary-container text-on-secondary-container font-semibold shadow-sm transition-colors';
        } else {
          link.className = 'flex items-center gap-space-md px-space-sm py-space-xs rounded text-on-surface-variant hover:bg-surface-container-high hover:text-on-surface transition-colors';
        }
      });
    })();

(function initSystemMonitor() {
      // Highlight sidebar 'System Monitor' item if matching nav element exists
      const currentNav = document.querySelector('aside nav a[data-path="system-monitor"]');
      if (currentNav) {
        document.querySelectorAll('aside nav a').forEach(el => {
          el.className = 'flex items-center gap-space-md px-space-sm py-space-xs rounded text-on-surface-variant hover:bg-surface-container-high hover:text-on-surface transition-colors';
        });
        currentNav.className = 'flex items-center gap-space-md px-space-sm py-space-xs rounded bg-secondary-container text-on-secondary-container font-semibold shadow-sm transition-colors';
      }

      // Garbage Collection Action trigger
      const gcBtn = document.getElementById('gcTriggerBtn');
      const terminal = document.getElementById('diagnosticTerminal');
      if (gcBtn && terminal) {
        gcBtn.addEventListener('click', () => {
          const originalText = gcBtn.innerHTML;
          gcBtn.innerHTML = '<span class="material-symbols-outlined text-[16px] animate-spin text-tertiary">sync</span><span>Reclaiming...</span>';
          gcBtn.classList.add('pointer-events-none', 'opacity-75');

          setTimeout(() => {
            const now = new Date();
            const timeStr = [now.getHours(), now.getMinutes(), now.getSeconds()]
              .map(v => String(v).padStart(2, '0'))
              .join(':');

            const logEntry = document.createElement('div');
            logEntry.className = 'flex items-start gap-2 bg-surface-container-high p-1 rounded animate-fade-in';
            logEntry.innerHTML = `
              <span class="font-label-mono text-label-mono text-primary">${timeStr}</span>
              <span class="px-1 rounded bg-secondary-container font-label-mono text-[9px] text-on-secondary-container font-semibold">GC_FORCE</span>
              <span class="text-on-surface font-semibold">Garbage collection executed. 182 MB stale KV memory purged.</span>
            `;
            terminal.insertBefore(logEntry, terminal.firstChild);

            gcBtn.innerHTML = originalText;
            gcBtn.classList.remove('pointer-events-none', 'opacity-75');
          }, 850);
        });
      }

      // Clear Buffer Button Action
      const cleanBtn = document.getElementById('cleanCacheBtn');
      if (cleanBtn && terminal) {
        cleanBtn.addEventListener('click', () => {
          cleanBtn.classList.add('bg-surface-container-highest');
          setTimeout(() => cleanBtn.classList.remove('bg-surface-container-highest'), 300);

          const now = new Date();
          const timeStr = [now.getHours(), now.getMinutes(), now.getSeconds()]
            .map(v => String(v).padStart(2, '0'))
            .join(':');

          const logEntry = document.createElement('div');
          logEntry.className = 'flex items-start gap-2 text-primary-container';
          logEntry.innerHTML = `
            <span class="font-label-mono text-label-mono">${timeStr}</span>
            <span class="px-1 rounded bg-surface-container-high font-label-mono text-[9px] text-primary font-semibold">FLUSH</span>
            <span class="text-on-surface">D:\\AI_Models\\GGUF swap buffers verified clean. Zero dangling locks.</span>
          `;
          terminal.insertBefore(logEntry, terminal.firstChild);
        });
      }

      // Clear logs terminal button
      const clearLogsBtn = document.getElementById('clearLogsBtn');
      if (clearLogsBtn && terminal) {
        clearLogsBtn.addEventListener('click', () => {
          terminal.innerHTML = `
            <div class="flex items-start gap-2 text-on-surface-variant font-label-mono text-label-mono">
              <span>-- Console cleared. Telemetry ring restarted. --</span>
            </div>
          `;
        });
      }

      // Export Diagnostic Report
      const exportDiagBtn = document.getElementById('exportDiagBtn');
      if (exportDiagBtn) {
        exportDiagBtn.addEventListener('click', () => {
          const reportPayload = {
            system: "Intel Core i3-6100T (2C/4T @ 3.20GHz)",
            ram: "12.0 GB DDR4 (7.8 GB used, 65%)",
            gpu: "Intel HD Graphics 530 (1.8 GB shared VRAM)",
            storage: "D:\\AI_Models\\GGUF (28.4 GB / 256 GB)",
            processes: [
              { name: "Mistral-7B-Instruct-v0.3", pid: 14022, memory: "4.18 GB", state: "ACTIVE" },
              { name: "DeepSeek-Coder-6.7B", pid: 14088, memory: "3.82 GB", state: "WARM STANDBY" },
              { name: "Whisper-Base-IN", pid: 14102, memory: "142 MB", state: "RUNNING" }
            ],
            airgapped: true,
            timestamp: new Date().toISOString()
          };
          const blob = new Blob([JSON.stringify(reportPayload, null, 2)], { type: 'application/json' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `system_diagnostic_report_${Date.now()}.json`;
          a.click();
          URL.revokeObjectURL(url);
        });
      }
    })();

(function initSecurityScreen() {
    // Master Pause Toggle Interaction
    const pauseBtn = document.getElementById('btn-master-pause');
    let isPaused = false;
    if (pauseBtn) {
      pauseBtn.addEventListener('click', () => {
        isPaused = !isPaused;
        const icon = pauseBtn.querySelector('.material-symbols-outlined');
        const text = pauseBtn.querySelector('span:not(.material-symbols-outlined)');
        if (isPaused) {
          pauseBtn.classList.remove('bg-surface-container-high', 'text-tertiary-fixed');
          pauseBtn.classList.add('bg-tertiary-fixed-dim', 'text-on-tertiary');
          icon.textContent = 'play_circle';
          text.textContent = 'RESUME AGENTS (UNFREEZE)';
        } else {
          pauseBtn.classList.add('bg-surface-container-high', 'text-tertiary-fixed');
          pauseBtn.classList.remove('bg-tertiary-fixed-dim', 'text-on-tertiary');
          icon.textContent = 'pause_circle';
          text.textContent = 'MASTER PAUSE (FREEZE ALL)';
        }
      });
    }

    // Kill Switch Safety Trigger
    const killBtn = document.getElementById('btn-kill-switch');
    if (killBtn) {
      killBtn.addEventListener('click', () => {
        const confirmed = window.confirm("CRITICAL WARNING: This will immediately sever all local agent IPC sockets, dump volatile memory to encrypted logs, and terminate all AppContainers. Proceed?");
        if (confirmed) {
          killBtn.innerHTML = `
            <span class="material-symbols-outlined text-[20px]">done_all</span>
            <span class="font-label-mono text-label-mono font-bold uppercase tracking-wider">ALL PROCESSES KILLED</span>
          `;
          killBtn.classList.remove('bg-error-container');
          killBtn.classList.add('bg-error', 'text-on-error');
        }
      });
    }
  })();
